def crawl_and_summarise(client, url, seen=set()):
    page = requests.get(url, timeout=10).text
    client.messages.create(model=MODEL, max_tokens=300, messages=[{"role": "user", "content": page}])
    for link in extract_links(page):
        if link not in seen:
            seen.add(link)
            crawl_and_summarise(client, link, seen)

